// 🚀 INTERPRETASI KCDA OTOMATIS (EXACT MATCH INTERPRETASI.DOCX & BPS MERGE)
// ==========================================
let interpretasiScope = "full"; // 'full', '1', '2', '3', '4', '5', '6', '7'
let interpretasiTone = "formal"; // 'formal', 'briefing', 'social'
let interpretasiLang = "id"; // 'id', 'en', 'bi'
let interpretasiCustomTexts = {}; // Key: `${distIndex}_${scope}_${tone}_${lang}` -> user edited text
let currentNarrativeScope = "bab";

// Helper to format raw official BPS ulasan text to rich HTML paragraphs
function formatRawUlasanToHtml(rawText, lang = "id", districtName = "") {
  if (!rawText || !rawText.trim()) return "";
  let clean = rawText
    .replace(/km\uFFFD/g, "km²")
    .replace(/km\u00B2/g, "km²")
    .replace(/km²/g, "km²")
    .replace(/km²²/g, "km²")
    .replace(/2024\uFFFD2025/g, "2024–2025")
    .replace(/20242025/g, "2024–2025")
    .replace(/\uFFFD/g, "–");
  
  const paras = clean.split(/\n+/).map(p => p.trim()).filter(p => p.length > 0);
  
  return paras.map(p => {
    if (p.startsWith("===") && p.endsWith("===")) {
      return `<h4 style="font-size: 13.5px; font-weight: 800; color: #1e40af; margin: 16px 0 8px; border-bottom: 1.5px dashed #cbd5e1; padding-bottom: 4px;">${p.replace(/=/g, '').trim()}</h4>`;
    }
    return `<p style="margin-bottom: 12px; line-height: 1.75;">${p}</p>`;
  }).join("");
}

// Helper to join array with natural conjunction
function joinWithAnd(arr, conj = "dan") {
  if (!arr || arr.length === 0) return "";
  if (arr.length === 1) return arr[0];
  if (arr.length === 2) return `${arr[0]} ${conj} ${arr[1]}`;
  return `${arr.slice(0, -1).join(", ")}, ${conj} ${arr[arr.length - 1]}`;
}

// Robust helper to check if a text/indicator value means unavailable/non-existent
function isUnavailable(val) {
  if (val === null || val === undefined) return true;
  const str = String(val).trim().toLowerCase();
  if (!str || str === '-' || str === '0' || str === 'none' || str === 'n/a' || str === 'null' || str === 'undefined' || str === 'belum' || str === 'tidak') return true;
  if (str.includes('tidak tersedia') || str.includes('tidak ada') || str.includes('belum tersedia') || str.includes('belum ada') || str.includes('nihil')) return true;
  return false;
}

