// Helper to translate single commodity name to English
function translateCommodityEn(str) {
  if (!str || str === '-' || isUnavailable(str)) return '-';
  const clean = String(str).trim().toLowerCase();
  if (COMMODITY_MAP_EN[clean]) return COMMODITY_MAP_EN[clean];
  if (clean.includes('/')) {
    const parts = clean.split('/').map(p => COMMODITY_MAP_EN[p.trim()] || p.trim());
    return parts.join(' / ');
  }
  return str.trim();
}

// Helper to translate comma/dan separated list of commodities and join with English 'and'
function translateCommodityListEn(rawList) {
  if (!rawList || rawList === '-' || isUnavailable(rawList)) return '-';
  const normalized = String(rawList).replace(/\bdan\b/gi, ',');
  const items = normalized.split(',').map(x => x.trim()).filter(Boolean);
  const translated = items.map(item => translateCommodityEn(item));
  if (translated.length === 0) return '';
  if (translated.length === 1) return translated[0];
  if (translated.length === 2) return `${translated[0]} and ${translated[1]}`;
  return `${translated.slice(0, -1).join(', ')}, and ${translated[translated.length - 1]}`;
}

// Helpers to translate facilities and indicators for other Babs
function translateHealthFacilityEn(rawStr) {
  if (!rawStr || rawStr === '-' || isUnavailable(rawStr)) return '';
  let str = String(rawStr).trim().toLowerCase();
  str = str.replace(/puskesmas rawat inap/g, "inpatient public health centers");
  str = str.replace(/puskesmas tanpa rawat inap/g, "non-inpatient public health centers");
  str = str.replace(/rumah sakit/g, "hospitals");
  str = str.replace(/apotek/g, "pharmacies");
  str = str.replace(/posyandu/g, "integrated healthcare posts (Posyandu)");
  str = str.replace(/balai pengobatan|klinik/g, "medical clinics");
  str = str.replace(/\bdan\b/gi, "and");
  return str;
}

