              <div class="card-stat-subtext-village" id="val-desa-tinggi-nama" data-field="desa_tinggi_nama" contenteditable="true">${babData.desa_tinggi_nama || babData.Desa_tertinggi || babData.desa_tertinggi || "-"}</div>
