// --- PARSING ZIP OR GEOJSON PETAMAP ---
function handleMapsUpload(e) {
  const file = e.target.files[0];
  if (!file) return;

  const extension = file.name.split('.').pop().toLowerCase();

  // 1. Handle GeoJSON
  if (extension === "geojson" || extension === "json") {
    const reader = new FileReader();
    reader.onload = function(evt) {
      try {
        geojsonData = JSON.parse(evt.target.result);
        
        let matchCount = 0;
        mapImages = {};
        
        districtsData.forEach(item => {
          const match = findMatchingFeature(item.nama);
          if (match) {
            mapImages[item.nama.toLowerCase().trim()] = "geojson";
            matchCount++;
          }
        });
        
        showToast("success", "GeoJSON Berhasil Dimuat", `Mencocokkan ${matchCount} dari ${districtsData.length} batas wilayah kecamatan.`);
        renderDistrictList();
        updatePreview();
        
        const fileInfo = document.getElementById("maps-file-info");
        if (fileInfo) {
          fileInfo.innerText = `GeoJSON loaded (${matchCount}/${districtsData.length} kec).`;
          fileInfo.style.display = "inline-flex";
        }
      } catch (err) {
        console.error(err);
        showToast("error", "Gagal Membaca GeoJSON", "Pastikan format berkas GeoJSON valid.");
      }
    };
    reader.readAsText(file);
    return;
  }

  // 2. Handle ZIP
  const zip = new JSZip();
  zip.loadAsync(file)
    .then(async (contents) => {
      let count = 0;
      const fileKeys = Object.keys(contents.files);
      
      geojsonData = null;
      mapImages = {};
      
      for (let filename of fileKeys) {
        const fileObj = contents.files[filename];
        if (fileObj.dir) continue;

        const extMatch = filename.match(/\.(png|jpg|jpeg|svg)$/i);
        if (extMatch) {
          const extension = extMatch[1].toLowerCase();
          const cleanName = filename.split('/').pop().replace(/\.(png|jpg|jpeg|svg)$/i, '').toLowerCase().trim();
          
          const data = await fileObj.async("arraybuffer");
          const mimeType = extension === 'svg' ? 'image/svg+xml' : `image/${extension === 'jpg' ? 'jpeg' : extension}`;
          const blob = new Blob([data], { type: mimeType });
          mapImages[cleanName] = URL.createObjectURL(blob);
          count++;
        }
      }

      showToast("success", "Peta ZIP Dimuat", `Berhasil memetakan ${count} gambar peta kecamatan.`);
      renderDistrictList();
      updatePreview();
      
      const fileInfo = document.getElementById("maps-file-info");
      if (fileInfo) {
        fileInfo.innerText = `${count} peta berhasil dicocokkan.`;
        fileInfo.style.display = "inline-flex";
      }
    })
    .catch(err => {
      console.error(err);
      showToast("error", "Gagal Membaca ZIP", "Pastikan berkas ZIP berisi file gambar peta yang valid.");
    });
}


