function loadInterpretasiExcel(file) {
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const data = new Uint8Array(evt.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      const sheetName = workbook.SheetNames[0];
      const ws = workbook.Sheets[sheetName];

      const rawRows = XLSX.utils.sheet_to_json(ws, { header: 1 });
      if (!rawRows || rawRows.length === 0) {
        showToast("error", "Berkas Kosong", "Berkas Excel tidak memiliki baris data.");
        return;
      }

      let headerIdx = -1;
      for (let r = 0; r < Math.min(10, rawRows.length); r++) {
        const row = rawRows[r] || [];
        const str = row.join(" ").toLowerCase();
        if (str.includes("kecamatan") || str.includes("executive_summary") || str.includes("ulasan_bab_1")) {
          headerIdx = r;
          break;
        }
      }

      let rowsToProcess = [];
      if (headerIdx !== -1) {
        rowsToProcess = XLSX.utils.sheet_to_json(ws, { range: headerIdx });
      } else {
        rowsToProcess = XLSX.utils.sheet_to_json(ws);
      }

      let matchedCount = 0;
      rowsToProcess.forEach(row => {
        const rawName = row.Kecamatan || row.kecamatan || row.NamaKec || row.nama_kecamatan || "";
        const name = String(rawName).trim().toUpperCase();
        const distIdx = KECAMATAN_LIST.findIndex(k => k.toUpperCase() === name);
        if (distIdx !== -1) {
          matchedCount++;

          // Map executive summary
          const execSummary = row.Executive_Summary || row.executive_summary || row.Ringkasan_Eksekutif || row.ringkasan_eksekutif || "";
          if (execSummary) {
            const key = `${distIdx}_full_formal_id`;
            interpretasiCustomTexts[key] = `<p>${execSummary.replace(/\n\n/g, '</p><p>').replace(/\n/g, '<br>')}</p>`;
          }

          // Map Bab 1 to 7
          for (let b = 1; b <= 7; b++) {
            const babText = row[`Ulasan_Bab_${b}`] || row[`Ulasan_Bab_${b}_Geografi`] || row[`Ulasan_Bab_${b}_Pemerintahan`] || row[`Ulasan_Bab_${b}_Penduduk`] || row[`Ulasan_Bab_${b}_Sosial`] || row[`Ulasan_Bab_${b}_Pertanian`] || row[`Ulasan_Bab_${b}_Transportasi`] || row[`Ulasan_Bab_${b}_Perdagangan`] || row[`Bab_${b}`] || row[`bab_${b}`] || "";
            if (babText) {
              const key = `${distIdx}_${b}_formal_id`;
              interpretasiCustomTexts[key] = `<p>${babText.replace(/\n\n/g, '</p><p>').replace(/\n/g, '<br>')}</p>`;
            }
          }
        }
      });

      if (matchedCount > 0) {
        renderInterpretasiKCDA();
        showToast("success", "Narasi Excel Terpasang", `Berhasil memuat ulasan narasi interpretasi untuk ${matchedCount} kecamatan!`);
      } else {
        showToast("warning", "Nama Kecamatan Tidak Cocok", "Pastikan kolom 'Kecamatan' memuat nama kecamatan yang sesuai (e.g. SUMUR, SAKETI, KORONCONG).");
      }
    } catch(err) {
      console.error("Interpretasi Excel error:", err);
      showToast("error", "Gagal Membaca Excel", err.message);
    }
  };
  reader.readAsArrayBuffer(file);
}

// --- KATEGORI 3: TEMPLATE METADATA NOMOR KATALOG, PUBLIKASI & ISSUE ---
function downloadKatalogIssueTemplate(mode = "preset") {
  const isBlank = (mode === "blank");
  const wb = XLSX.utils.book_new();

  const headers = [
    "No",
    "Kecamatan",
    "Kode_Katalog",
    "No_Publikasi",
    "No_ISSN",
    "No_ISBN",
    "District_in_Figures",
    "No_Volume_Issue",
    "Tahun_Rilis",
    "Tim_Penyusun"
  ];

  const rows = KECAMATAN_LIST.map((kec, idx) => {
    if (isBlank) {
      return [idx + 1, kec, "", "", "", "", `${kec.charAt(0) + kec.slice(1).toLowerCase()} District in Figures`, "", "2026", "BPS Kabupaten Pandeglang"];
    }
    const preset = (OFFICIAL_COVER_METADATA_PRESET && OFFICIAL_COVER_METADATA_PRESET[idx]) || {};
    const kat = preset.kode || `1102001.3601${String(idx + 1).padStart(3, '0')}`;
    const issn = preset.issn ? `ISSN ${preset.issn}` : "ISSN 2964-6723";
    const pub = `36010.26${String(idx + 1).padStart(2, '0')}`;
    const isbn = "-";
    const eng = preset.english || `${kec.charAt(0) + kec.slice(1).toLowerCase()} District in Figures`;
    const vol = preset.volume || "Volume 17, 2026";
    return [
      idx + 1,
      kec,
      kat,
      pub,
      issn,
      isbn,
      eng,
      vol,
      "2026",
      "BPS Kabupaten Pandeglang"
    ];
  });

  const subText = isBlank ? "Formulir Metadata Kosong" : "Metadata Resmi 35 Kecamatan";
  const wsData = [
    ["TEMPLATE METADATA NOMOR KATALOG, PUBLIKASI, & ISSUE KCDA 35 KECAMATAN - BPS PANDEGLANG"],
    [`Formulir resmi nomor katalog BPS, nomor publikasi, nomor ISSN/ISBN, dan volume issue untuk Cover Publikasi - [${subText}]`],
    ["Petunjuk: Perbarui nomor katalog atau issue sesuai ketetapan BPS. Jangan ubah baris nama kolom (Baris 5)!"],
    [],
    headers,
    ...rows
  ];

  const ws = XLSX.utils.aoa_to_sheet(wsData);
  ws['!cols'] = [
    { wch: 6 },  // No
    { wch: 18 }, // Kecamatan
    { wch: 22 }, // No Katalog
    { wch: 18 }, // No Publikasi
    { wch: 18 }, // No ISSN
    { wch: 18 }, // No ISBN
    { wch: 32 }, // District in Figures
    { wch: 20 }, // Volume Issue
    { wch: 14 }, // Tahun
    { wch: 26 }  // Tim Penyusun
  ];

  XLSX.utils.book_append_sheet(wb, ws, "Metadata_Katalog_Issue");
  const fileName = isBlank ? "Template_Metadata_Katalog_Issue_Format_Kosong.xlsx" : "Template_Metadata_Katalog_Issue_35_Kecamatan.xlsx";
  XLSX.writeFile(wb, fileName);
  showToast("success", "Template Metadata Diunduh", `Berkas '${fileName}' berhasil diunduh.`);
}

// Helper to temporarily hide elements with 0 width/height that have gradients, preventing html2canvas from throwing addColorStop crashes on 0 dimensions.
function hideZeroDimensionGradients(container) {
  const zeroElements = [];
  container.querySelectorAll(".chart-bar-fill, .pencil-fill, .thermometer-modern-fill, div, span, svg, i").forEach(el => {
    try {
      const computedStyle = window.getComputedStyle(el);
      const bgImage = computedStyle.backgroundImage || "";
      const hasGradient = bgImage.includes("gradient");
      
      const rect = el.getBoundingClientRect();
      const isZero = rect.width === 0 || rect.height === 0 || el.offsetWidth === 0 || el.offsetHeight === 0;
      
      if (hasGradient && isZero) {
        zeroElements.push({ el, originalDisplay: el.style.display });
        el.style.display = "none";
      }
    } catch (e) {
      // Ignore if computed style cannot be read
    }
  });
  return () => {
    zeroElements.forEach(item => {
      item.el.style.display = item.originalDisplay;
    });
  };
}

// Helper to temporarily convert SVGs with gradients or stroke-dasharray (like circular gauges and rings) to data URI images for html2canvas to render correctly.
function convertSvgsToImages(container) {
  const svgs = container.querySelectorAll("svg.circular-gauge-svg, svg.activity-ring-svg");
  const restores = [];
  
  svgs.forEach(svg => {
    try {
      const rect = svg.getBoundingClientRect();
      const width = rect.width || svg.clientWidth || 80;
      const height = rect.height || svg.clientHeight || 80;
      
      const serializer = new XMLSerializer();
      let svgString = serializer.serializeToString(svg);
      
      if (!svgString.includes('xmlns="http://www.w3.org/2000/svg"')) {
        svgString = svgString.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
      }
      
      // Inject globaldefs to resolve gradients inside the sandboxed data URI
      const globalDefs = document.querySelector("#infographic-element svg defs");
      if (globalDefs && !svgString.includes("<defs>")) {
        const defsString = serializer.serializeToString(globalDefs);
        svgString = svgString.replace(/^<svg([^>]*)>/, `<svg$1>${defsString}`);
      }
      
      const img = document.createElement("img");
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgString);
      img.style.width = `${width}px`;
      img.style.height = `${height}px`;
      img.style.display = "block";
      
      // Copy classes and styles
      img.className = svg.className.baseVal || svg.className || "";
      img.style.cssText = svg.style.cssText;
      
      const parent = svg.parentNode;
      parent.insertBefore(img, svg);
      svg.style.display = "none";
      
      restores.push(() => {
        parent.removeChild(img);
        svg.style.display = "";
      });
    } catch (e) {
      console.error("Error converting SVG to image:", e);
    }
  });
  
  return () => {
    restores.forEach(restore => restore());
  };
}

// --- HELPER TO IDENTIFY PRESSED BUTTON OR DEFAULT ---
function getButtonElement(param, defaultId) {
  if (param && param.target) {
    return param.target.closest("button") || document.getElementById(defaultId);
  }
  if (param instanceof HTMLElement) {
    return param;
  }
  return document.getElementById(defaultId);
}

// --- PREPARE VIEW FOR EXPORT (ENABLES RENDERING WHEN ON OTHER TABS) ---
function prepareExportView() {
  const viewEditor = document.getElementById("view-editor");
  if (!viewEditor) return () => {};
  
  const wasActive = viewEditor.classList.contains("active");
  const origStyle = {
    display: viewEditor.style.display,
    position: viewEditor.style.position,
    left: viewEditor.style.left,
    top: viewEditor.style.top,
    visibility: viewEditor.style.visibility,
    opacity: viewEditor.style.opacity,
    zIndex: viewEditor.style.zIndex
  };
  
  if (!wasActive) {
    viewEditor.style.display = "flex";
    viewEditor.style.position = "fixed";
    viewEditor.style.left = "-9999px";
    viewEditor.style.top = "0";
    viewEditor.style.visibility = "visible";
    viewEditor.style.opacity = "1";
    viewEditor.style.zIndex = "-9999";
  }
  
  return () => {
    if (!wasActive) {
      viewEditor.style.display = origStyle.display;
      viewEditor.style.position = origStyle.position;
      viewEditor.style.left = origStyle.left;
      viewEditor.style.top = origStyle.top;
      viewEditor.style.visibility = origStyle.visibility;
      viewEditor.style.opacity = origStyle.opacity;
      viewEditor.style.zIndex = origStyle.zIndex;
    }
  };
}

// --- UNIFIED HIGH-QUALITY HTML2CANVAS RENDER HELPER ---
async function renderInfographicCanvas(scale = 2.5) {
  const element = document.getElementById("infographic-element");
  const restoreZero = hideZeroDimensionGradients(element);
  const restoreSvgs = convertSvgsToImages(element);
  
  try {
    const canvas = await html2canvas(element, {
      scale: scale,
      logging: false,
      useCORS: true,
      allowTaint: true,
      onclone: (clonedDoc) => {
        // 1. Disable all CSS transitions & animations in clone
        const style = clonedDoc.createElement("style");
        style.innerHTML = "* { transition: none !important; animation: none !important; }";
        clonedDoc.head.appendChild(style);
        
        // 2. Ensure view-editor is active and visible in cloned doc
        const clonedEditor = clonedDoc.getElementById("view-editor");
        if (clonedEditor) {
          clonedEditor.style.display = "flex";
          clonedEditor.style.position = "static";
          clonedEditor.style.visibility = "visible";
          clonedEditor.style.opacity = "1";
        }
        
        // 3. Clean any 0-dimension gradient elements in clone to guarantee addColorStop never throws
        const clonedInfo = clonedDoc.getElementById("infographic-element");
        if (clonedInfo) {
          clonedInfo.querySelectorAll("*").forEach(el => {
            const cs = clonedDoc.defaultView ? clonedDoc.defaultView.getComputedStyle(el) : null;
            const bg = (cs && cs.backgroundImage) || el.style.backgroundImage || "";
            if (bg.includes("gradient")) {
              const r = el.getBoundingClientRect();
              if (r.width < 1 || r.height < 1 || el.offsetWidth < 1 || el.offsetHeight < 1) {
                el.style.backgroundImage = "none";
                el.style.background = "transparent";
                el.style.display = "none";
              }
            }
          });
        }
      }
    });
    return canvas;
  } finally {
    restoreZero();
    restoreSvgs();
  }
}

// --- EXPORT SINGLE PNG ---
async function exportSinglePNG(btnOrEvent) {
  const btn = getButtonElement(btnOrEvent, "btn-export-png");
  const originalText = btn ? btn.innerHTML : "Unduh Gambar (PNG)";
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = `Mengekspor...`;
  }

  const restoreView = prepareExportView();

  try {
    const canvas = await renderInfographicCanvas(3);
    const districtName = districtsData[activeIndex] ? districtsData[activeIndex].nama : "Kecamatan";
    const link = document.createElement("a");
    link.download = `Bab${activeBab}_Infografis_${districtName}.png`;
    link.href = canvas.toDataURL("image/png");
    link.click();
    showToast("success", "Ekspor PNG Berhasil", `Infografis Bab ${activeBab} (${districtName}) berhasil diunduh dalam resolusi HD.`);
  } catch (err) {
    console.error("Export PNG Error:", err);
    showToast("error", "Gagal Ekspor PNG", "Terjadi kesalahan: " + (err.message || err));
  } finally {
    restoreView();
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalText;
    }
  }
}

// --- EXPORT MASSAL (ZIP) ---
async function exportAllPNGs(btnOrEvent) {
  const btn = getButtonElement(btnOrEvent, "btn-export-all");
  const originalText = btn ? btn.innerHTML : "Unduh Berkas ZIP";
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = "Memproses...";
  }
  
  const overlay = document.getElementById("rendering-overlay");
  const progressText = document.getElementById("render-progress-text");
  const progressPercent = document.getElementById("render-progress-percent");
  const progressFill = document.getElementById("render-progress-fill");
  
  if (overlay) overlay.style.display = "flex";
  
  const restoreView = prepareExportView();
  const zip = new JSZip();
  const folder = zip.folder(`infografis-bab-${activeBab}`);
  const originalActiveIndex = activeIndex;

  try {
    for (let i = 0; i < districtsData.length; i++) {
      activeIndex = i;
      updatePreview();
      
      const percent = Math.round(((i + 1) / districtsData.length) * 100);
      if (progressText) progressText.innerText = `Memproses: Bab ${activeBab} - ${districtsData[i].nama} (${i + 1} dari ${districtsData.length})`;
      if (progressPercent) progressPercent.innerText = `${percent}%`;
      if (progressFill) progressFill.style.width = `${percent}%`;

      await new Promise(resolve => setTimeout(resolve, 80));
      
      const canvas = await renderInfographicCanvas(2.5);
      const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
      folder.file(`${districtsData[i].no}_Bab${activeBab}_Infografis_${districtsData[i].nama}.png`, blob);
    }
    
    if (progressText) progressText.innerText = `Mengompresi ke ZIP...`;
    const zipBlob = await zip.generateAsync({ type: "blob" });
    
    const link = document.createElement("a");
    link.href = URL.createObjectURL(zipBlob);
    link.download = `Infografis_KCDA_Bab${activeBab}_35_Kecamatan.zip`;
    link.click();
    showToast("success", "Generate Massal Selesai", `Seluruh ${districtsData.length} infografis Bab ${activeBab} berhasil dikemas ke dalam berkas ZIP.`);
    
  } catch (err) {
    console.error("Export ZIP Error:", err);
    showToast("error", "Gagal Generate Massal", "Terjadi kesalahan ekspor massal: " + (err.message || err));
  } finally {
    try {
      activeIndex = Math.max(0, Math.min(originalActiveIndex, districtsData.length - 1));
      updatePreview();
      renderDistrictList();
    } catch (e) {
      console.warn("Cleanup warning:", e);
    }
    
    try {
      restoreView();
    } catch (e) {}
    
    if (overlay) overlay.style.display = "none";
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalText;
    }
  }
}

// --- EXPORT MULTIPAGE BOOKLET PDF (Bab 1 s.d. Bab 7 Lengkap untuk Kecamatan Aktif) ---
async function exportDistrictBookletPDF(btnOrEvent) {
  const btn = (btnOrEvent && (btnOrEvent.target || btnOrEvent.currentTarget)) 
    ? (btnOrEvent.target.closest ? (btnOrEvent.target.closest("button") || btnOrEvent.target) : btnOrEvent) 
    : (document.getElementById("btn-export-booklet-pdf-editor") || document.getElementById("btn-export-pdf-tab"));
    
  const originalText = btn ? btn.innerHTML : "Unduh Dokumen PDF";
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = "<span>⏳ Menyusun PDF...</span>";
  }
  
  const overlay = document.getElementById("rendering-overlay");
  const progressText = document.getElementById("render-progress-text");
  const progressPercent = document.getElementById("render-progress-percent");
  const progressFill = document.getElementById("render-progress-fill");
  
  if (overlay) overlay.style.display = "flex";
  
  const restoreView = prepareExportView();
  const { jsPDF } = window.jspdf;
  // A5 Portrait format (148 x 210 mm) matching BPS publication standards
  const pdf = new jsPDF({
    orientation: "p",
    unit: "mm",
    format: "a5",
    compress: true
  });
  
  const originalActiveBab = activeBab;
  const originalActiveIndex = activeIndex;
  const currentDistrict = (districtsData && districtsData[activeIndex]) || { nama: "KECAMATAN" };
  const districtName = (currentDistrict.nama || "KECAMATAN").toUpperCase();
  
  const BAB_NAMES = {
    0: "Cover Depan Buku KCDA",
    1: "Geografi & Iklim",
    2: "Pemerintahan",
    3: "Kependudukan",
    4: "Sosial & Kesra",
    5: "Pertanian",
    6: "Transportasi & Komunikasi",
    7: "Perdagangan & Koperasi"
  };

  try {
    for (let bab = 0; bab <= 7; bab++) {
      activeBab = bab;
      
      // Update visual tabs
      document.querySelectorAll(".bab-tab").forEach(tab => {
        if (parseInt(tab.getAttribute("data-bab")) === bab) {
          tab.classList.add("active");
        } else {
          tab.classList.remove("active");
        }
      });
      
      updatePreview();
      
      const stepIndex = bab + 1;
      const totalSteps = 8;
      const percent = Math.round((stepIndex / totalSteps) * 100);
      const labelText = (bab === 0) ? `Merender Cover Depan Buku KCDA (${districtName})` : `Merender Bab ${bab} dari 7: ${BAB_NAMES[bab]} (${districtName})`;
      if (progressText) progressText.innerText = labelText;
      if (progressPercent) progressPercent.innerText = `${percent}%`;
      if (progressFill) progressFill.style.width = `${percent}%`;

      // Allow charts and DOM to paint fully
      await new Promise(resolve => setTimeout(resolve, 150));
      
      const canvas = await renderInfographicCanvas(2);
      const imgData = canvas.toDataURL("image/jpeg", 0.92);
      
      if (bab > 0) {
        pdf.addPage("a5", "p");
      }
      pdf.addImage(imgData, "JPEG", 0, 0, 148, 210, undefined, "FAST");
    }
    
    if (progressText) progressText.innerText = `Menyimpan Berkas PDF...`;
    const fileName = `Buku_KCDA_2024_${districtName}_Cover_dan_7Bab_Lengkap.pdf`;
    pdf.save(fileName);
    showToast("success", "Buku PDF Berhasil Dibuat", `Buku KCDA lengkap (Cover + 7 Bab) untuk Kecamatan ${districtName} siap dicetak.`);
    
  } catch (err) {
    console.error("Export PDF Error:", err);
    showToast("error", "Gagal Ekspor PDF", "Terjadi kesalahan penyusunan PDF: " + (err.message || err));
  } finally {
    try {
      activeBab = originalActiveBab;
      activeIndex = originalActiveIndex;
      document.querySelectorAll(".bab-tab").forEach(tab => {
        if (parseInt(tab.getAttribute("data-bab")) === activeBab) {
          tab.classList.add("active");
        } else {
          tab.classList.remove("active");
        }
      });
      updatePreview();
    } catch (e) {
      console.warn("Cleanup warning:", e);
    }
    
    try {
      restoreView();
    } catch (e) {}
    
    if (overlay) overlay.style.display = "none";
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalText;
    }
  }
}

