// --- HELPER FUNCTIONS ---
function formatNumber(num, decimals = 2) {
  if (num === undefined || num === null || num === "") return "0";
  if (typeof num === "string") {
    num = parseFloat(num.replace(/,/g, '.'));
  }
  if (isNaN(num)) return "0";
  if (num % 1 !== 0) {
    const factor = Math.pow(10, decimals);
    const rounded = Math.round(num * factor) / factor;
    return rounded.toString().replace(".", ",");
  }
  return num.toString();
}

function formatThousand(num) {
  if (num === undefined || num === null || isNaN(num)) return "0";
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

function formatJalanKondisiPercent(val) {
  if (val === undefined || val === null) return 0;
  const num = parseInt(val);
  if (!isNaN(num)) return num;
  const upper = String(val).toUpperCase().trim();
  if (upper === "BAIK") return 85;
  if (upper === "SEDANG") return 57;
  if (upper === "RUSAK") return 30;
  return 0;
}

function getLabel(key, defaultVal) {
  return customLabels[key] !== undefined ? customLabels[key] : defaultVal;
}

function renderMainIllustration(defaultSvgHtml, style = "") {
  return defaultSvgHtml;
}

function renderMap(districtName) {
  const mapWrapper = document.getElementById("map-card-wrapper");
  if (!mapWrapper) return;
  mapWrapper.innerHTML = "";

  const name = (typeof districtName === "object" && districtName !== null) ? districtName.nama : districtName;
  const cleanName = name.toLowerCase().trim();

  // 1. Try GeoJSON rendering of the specific active district only
  const match = findMatchingFeature(name);
  if (match && match.geometry) {
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("viewBox", "0 0 280 200");
    svg.setAttribute("class", "fallback-svg-map");
    
    // Project only the single matched feature to fit/zoom into the container
    const pathData = geojsonToSvgPath(match.geometry, 280, 200);
    
    if (pathData) {
      const pathEl = document.createElementNS("http://www.w3.org/2000/svg", "path");
      pathEl.setAttribute("d", pathData);
      pathEl.setAttribute("fill", "rgba(99, 102, 241, 0.85)"); // Highlight active district
      pathEl.setAttribute("stroke", "#ffffff");
      pathEl.setAttribute("stroke-width", "2");
      pathEl.setAttribute("filter", "drop-shadow(0 4px 8px rgba(99, 102, 241, 0.8))");
      svg.appendChild(pathEl);
      
      // Add label text centered
      const textEl = document.createElementNS("http://www.w3.org/2000/svg", "text");
      textEl.setAttribute("x", "140");
      textEl.setAttribute("y", "190");
      textEl.setAttribute("text-anchor", "middle");
      textEl.setAttribute("fill", "white");
      textEl.setAttribute("font-family", "Outfit, sans-serif");
      textEl.setAttribute("font-size", "12px");
      textEl.setAttribute("font-weight", "800");
      textEl.setAttribute("text-shadow", "0 2px 4px rgba(0,0,0,0.8)");
      textEl.textContent = name.toUpperCase();
      svg.appendChild(textEl);
      
      mapWrapper.appendChild(svg);
      return;
    }
  }

  // 2. Fallback to image URLs or deterministic layout
  const mapUrl = mapImages[cleanName];
  if (mapUrl && mapUrl !== "geojson") {
    const img = document.createElement("img");
    img.src = mapUrl;
    img.className = "map-image";
    img.alt = `Peta Kecamatan ${name}`;
    mapWrapper.appendChild(img);
  } else {
    const svgMap = generateDeterministicSvgMap(name);
    mapWrapper.appendChild(svgMap);
  }
}

function findMatchingFeature(districtName) {
  if (!geojsonData || !geojsonData.features) return null;
  const target = districtName.toLowerCase().trim();
  
  for (let feature of geojsonData.features) {
    if (!feature.properties) continue;
    
    for (let key of Object.keys(feature.properties)) {
      const val = feature.properties[key];
      if (typeof val === 'string') {
        const cleanVal = val.toLowerCase().trim();
        if (cleanVal === target || cleanVal.replace(/kecamatan\s+/g, '') === target) {
          return feature;
        }
      }
    }
  }
  return null;
}

function geojsonToSvgPath(geometry, width, height) {
  let points = [];
  
  function extractPoints(coords) {
    if (typeof coords[0] === 'number') {
      points.push({ lon: coords[0], lat: coords[1] });
    } else {
      coords.forEach(extractPoints);
    }
  }
  
  extractPoints(geometry.coordinates);

  if (points.length === 0) return "";

  let minLon = Math.min(...points.map(p => p.lon));
  let maxLon = Math.max(...points.map(p => p.lon));
  let minLat = Math.min(...points.map(p => p.lat));
  let maxLat = Math.max(...points.map(p => p.lat));

  let dLon = maxLon - minLon;
  let dLat = maxLat - minLat;

  if (dLon === 0) dLon = 0.0001;
  if (dLat === 0) dLat = 0.0001;

  let scaleX = width / dLon;
  let scaleY = height / dLat;
  let scale = Math.min(scaleX, scaleY) * 0.9; // 90% scale to leave 10% padding

  let offsetX = (width - dLon * scale) / 2;
  let offsetY = (height - dLat * scale) / 2;

  function project(lon, lat) {
    let px = (lon - minLon) * scale + offsetX;
    let py = height - ((lat - minLat) * scale + offsetY); // invert Y
    return `${px.toFixed(1)},${py.toFixed(1)}`;
  }

  let path = "";
  if (geometry.type === "Polygon") {
    geometry.coordinates.forEach(ring => {
      let ringPath = ring.map((pt, idx) => `${idx === 0 ? 'M' : 'L'}${project(pt[0], pt[1])}`).join(" ");
      path += ringPath + " Z ";
    });
  } else if (geometry.type === "MultiPolygon") {
    geometry.coordinates.forEach(poly => {
      poly.forEach(ring => {
        let ringPath = ring.map((pt, idx) => `${idx === 0 ? 'M' : 'L'}${project(pt[0], pt[1])}`).join(" ");
        path += ringPath + " Z ";
      });
    });
  }
  return path;
}

function generateDeterministicSvgMap(districtName) {
  const seedOffset = globalSettings.designSeedOffset || 0;
  const hash = getHashOfString(districtName) + seedOffset;
  
  let rngVal = hash;
  const seededRandom = () => {
    rngVal = (rngVal * 9301 + 49297) % 233280;
    return rngVal / 233280;
  };

  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 300 300");
  svg.setAttribute("class", "fallback-svg-map");

  const cx = 150;
  const cy = 150;
  const villageCount = Math.floor(seededRandom() * 4) + 6; 
  
  const outlinePoints = [];
  const baseRadius = 85 + (seededRandom() * 20);
  
  for (let i = 0; i < villageCount; i++) {
    const angle = (i * 2 * Math.PI / villageCount) + (seededRandom() * 0.3 - 0.15);
    const r = baseRadius * (0.8 + (seededRandom() * 0.4));
    outlinePoints.push({
      x: cx + r * Math.cos(angle),
      y: cy + r * Math.sin(angle),
      angle: angle
    });
  }

  const centerHubX = cx + (seededRandom() * 25 - 12.5);
  const centerHubY = cy + (seededRandom() * 25 - 12.5);

  for (let i = 0; i < villageCount; i++) {
    const p1 = outlinePoints[i];
    const p2 = outlinePoints[(i + 1) % villageCount];
    
    const midAngle = (p1.angle + p2.angle) / 2;
    const midR = baseRadius * (0.7 + (seededRandom() * 0.3));
    
    const color = PASTEL_COLORS[Math.floor(seededRandom() * PASTEL_COLORS.length)];
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    
    const d = `
      M ${centerHubX} ${centerHubY}
      Q ${(centerHubX + p1.x)/2 + (seededRandom()*10-5)} ${(centerHubY + p1.y)/2 + (seededRandom()*10-5)} ${p1.x} ${p1.y}
      A ${baseRadius} ${baseRadius} 0 0 1 ${p2.x} ${p2.y}
      Q ${(centerHubX + p2.x)/2 + (seededRandom()*10-5)} ${(centerHubY + p2.y)/2 + (seededRandom()*10-5)} ${centerHubX} ${centerHubY}
      Z
    `;
    
    path.setAttribute("d", d);
    path.setAttribute("fill", color);
    
    const labelX = (centerHubX + p1.x + p2.x) / 3;
    const labelY = (centerHubY + p1.y + p2.y) / 3;

    svg.appendChild(path);

    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
    text.setAttribute("x", labelX);
    text.setAttribute("y", labelY);
    text.textContent = `DESA ${i+1}`;
    svg.appendChild(text);
  }

  const outerBorder = document.createElementNS("http://www.w3.org/2000/svg", "path");
  let borderD = `M ${outlinePoints[0].x} ${outlinePoints[0].y} `;
  for(let i = 1; i < outlinePoints.length; i++){
    borderD += `L ${outlinePoints[i].x} ${outlinePoints[i].y} `;
  }
  borderD += "Z";
  outerBorder.setAttribute("d", borderD);
  outerBorder.setAttribute("fill", "none");
  outerBorder.setAttribute("stroke", "#ffffff");
  outerBorder.setAttribute("stroke-width", "4");
  outerBorder.setAttribute("filter", "drop-shadow(0 4px 6px rgba(0,0,0,0.3))");
  svg.appendChild(outerBorder);

  return svg;
}

function getHashOfString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  return Math.abs(hash);
}

function generateFloatingWaves() {
  const leftContainer = document.getElementById("wavy-left");
  const rightContainer = document.getElementById("wavy-right");
  const bgGrid = document.querySelector(".info-bg-grid");
  if (!leftContainer || !rightContainer) return;

  const patternIndex = globalSettings.bgPatternIndex || 0;
  
  // 1. Update background grid pattern dynamically (Corak)
  if (bgGrid) {
    if (patternIndex === 0) {
      bgGrid.style.backgroundImage = `
        linear-gradient(rgba(255, 255, 255, 0.05) 1.5px, transparent 1.5px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1.5px, transparent 1.5px)
      `;
      bgGrid.style.backgroundSize = "50px 50px";
    } else if (patternIndex === 1) {
      bgGrid.style.backgroundImage = "radial-gradient(rgba(255, 255, 255, 0.08) 1.5px, transparent 1.5px)";
      bgGrid.style.backgroundSize = "25px 25px";
    } else if (patternIndex === 2) {
      bgGrid.style.backgroundImage = `
        linear-gradient(45deg, rgba(255, 255, 255, 0.02) 25%, transparent 25%, 
        transparent 50%, rgba(255, 255, 255, 0.02) 50%, 
        rgba(255, 255, 255, 0.02) 75%, transparent 75%, transparent)
      `;
      bgGrid.style.backgroundSize = "40px 40px";
    } else {
      bgGrid.style.backgroundImage = "none";
    }
  }

  // 2. Generate side vectors (Corak samping)
  const createSideSVG = () => {
    let paths = "";
    if (patternIndex === 0) {
      // Waves
      for (let i = 0; i < 12; i++) {
        const xOffset = i * 12;
        paths += `<path d="M ${-40 + xOffset},0 C ${100 + xOffset},150 ${-120 + xOffset},350 ${130 + xOffset},600 C ${30 + xOffset},750 ${-80 + xOffset},950 ${150 + xOffset},1100" stroke="white" stroke-width="1.2" stroke-opacity="${0.25 - (i * 0.015)}" fill="none" />`;
      }
    } else if (patternIndex === 1) {
      // Diagonal tech stripes
      for (let i = 0; i < 25; i++) {
        const yOffset = i * 45;
        paths += `<line x1="0" y1="${yOffset}" x2="200" y2="${yOffset - 100}" stroke="white" stroke-width="1" stroke-opacity="0.12" />`;
        paths += `<circle cx="${10 + i*6}" cy="${yOffset + 20}" r="2" fill="white" opacity="0.15" />`;
      }
    } else if (patternIndex === 2) {
      // Floating rings
      for (let i = 0; i < 6; i++) {
        const cyVal = 150 + i * 170;
        const cxVal = 30 + (i % 2 === 0 ? 50 : 20);
        paths += `<circle cx="${cxVal}" cy="${cyVal}" r="60" stroke="white" stroke-width="1" stroke-opacity="0.08" fill="none" />`;
        paths += `<circle cx="${cxVal}" cy="${cyVal}" r="30" stroke="white" stroke-width="0.7" stroke-opacity="0.05" fill="none" />`;
      }
    } else {
      // Crosses & target marks
      for (let i = 0; i < 8; i++) {
        const cyVal = 100 + i * 130;
        const cxVal = 40 + (i % 2 === 0 ? 60 : 30);
        paths += `<line x1="${cxVal - 8}" y1="${cyVal}" x2="${cxVal + 8}" y2="${cyVal}" stroke="white" stroke-width="1" stroke-opacity="0.15" />`;
        paths += `<line x1="${cxVal}" y1="${cyVal - 8}" x2="${cxVal}" y2="${cyVal + 8}" stroke="white" stroke-width="1" stroke-opacity="0.15" />`;
        paths += `<circle cx="${cxVal}" cy="${cyVal}" r="4" stroke="white" stroke-width="0.8" stroke-opacity="0.1" fill="none" />`;
      }
    }
    return `
      <svg width="220" height="1100" viewBox="0 0 220 1100" fill="none" xmlns="http://www.w3.org/2000/svg">
        ${paths}
      </svg>
    `;
  };

  const svgContent = createSideSVG();
  leftContainer.innerHTML = svgContent;
  rightContainer.innerHTML = svgContent;
}

// --- NEW REVISION FUNCTIONS ---
function getRomanNumeral(num) {
  const roman = { 1: "I", 2: "II", 3: "III", 4: "IV", 5: "V", 6: "VI", 7: "VII" };
  return roman[num] || String(num);
}

function hexToRgba(hex, opacity) {
  const shorthandRegex = /^#?([a-f\d])([a-f\d])([a-f\d])$/i;
  const fullHex = hex.replace(shorthandRegex, (m, r, g, b) => r + r + g + g + b + b);
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(fullHex);
  if (result) {
    const r = parseInt(result[1], 16);
    const g = parseInt(result[2], 16);
    const b = parseInt(result[3], 16);
    return `rgba(${r}, ${g}, ${b}, ${opacity})`;
  }
  return `rgba(15, 23, 42, ${opacity})`;
}

