function getIcon(key, defaultSvgHtml) {
  globalSettings.customIcons = globalSettings.customIcons || {};
  let svgHtml = defaultSvgHtml;
  
  const val = globalSettings.customIcons[key] || DEFAULT_ICON_MAP[key];
  if (val) {
    if (val.startsWith("data:image/")) {
      return `<img src="${val}" class="custom-icon-image" style="width: 32px; height: 32px; object-fit: contain;">`;
    }
    const presetName = val;
    if (ICON_PRESETS[presetName]) {
      const wMatch = defaultSvgHtml.match(/width="([^"]+)"/);
      const hMatch = defaultSvgHtml.match(/height="([^"]+)"/);
      let presetSvg = ICON_PRESETS[presetName];
      if (wMatch) presetSvg = presetSvg.replace(/width="22"/, `width="${wMatch[1]}"`);
      if (hMatch) presetSvg = presetSvg.replace(/height="22"/, `height="${hMatch[1]}"`);
      return presetSvg;
    }
  }
  
  // Dynamically map solid outlines to gorgeous glowing duo-tone gradients
  svgHtml = svgHtml.replace(/stroke="#f472b6"/g, 'stroke="url(#svg-grad-rose)"');
  svgHtml = svgHtml.replace(/stroke="#34d399"/g, 'stroke="url(#svg-grad-teal)"');
  svgHtml = svgHtml.replace(/stroke="#cbd5e1"/g, 'stroke="url(#svg-grad-primary)"');
  svgHtml = svgHtml.replace(/stroke="#fde047"/g, 'stroke="url(#svg-grad-accent)"');
  svgHtml = svgHtml.replace(/stroke="#60a5fa"/g, 'stroke="url(#svg-grad-primary)"');
  svgHtml = svgHtml.replace(/stroke="currentColor"/g, 'stroke="url(#svg-grad-primary)"');
  
  return svgHtml;
}

