function applyBackgroundDecorations() {
  const container = document.getElementById("bg-decorations");
  if (!container) return;
  
  // If we don't have bgDecorItems yet, initialize them
  if (!globalSettings.bgDecorItems) {
    randomizeBackgroundDecorations();
    return;
  }
  
  container.innerHTML = "";
  
  // If background model is custom image, hide elements to avoid cluttering
  const bgStyle = globalSettings.bgStyle || "mesh";
  if (bgStyle === "image") {
    return;
  }

  const items = globalSettings.bgDecorItems;
  const theme = globalSettings.bgDecorTheme || 0;

  items.forEach(item => {
    const el = document.createElement("div");
    el.className = "bg-decor-item";
    el.style.left = item.left;
    el.style.top = item.top;
    el.style.width = item.size;
    el.style.height = item.size;
    el.style.opacity = item.opacity;
    el.style.transform = `rotate(${item.rotation}deg)`;

    let svgContent = "";
    if (theme === 0) {
      // Tech crosshairs / reticles
      svgContent = `
        <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.2">
          <line x1="12" y1="2" x2="12" y2="22" />
          <line x1="2" y1="12" x2="22" y2="12" />
          <circle cx="12" cy="12" r="6" stroke-dasharray="2,2" />
        </svg>
      `;
    } else if (theme === 1) {
      // Organic bubbles / concentric rings
      svgContent = `
        <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1">
          <circle cx="12" cy="12" r="10" />
          <circle cx="12" cy="12" r="5" stroke-dasharray="3,3" />
        </svg>
      `;
    } else if (theme === 2) {
      // Retro polygons (triangles / diamonds)
      svgContent = `
        <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.2">
          <polygon points="12,2 22,12 12,22 2,12" />
        </svg>
      `;
    } else {
      // Minimalist dust / stars
      svgContent = `
        <svg width="100%" height="100%" viewBox="0 0 24 24" fill="white">
          <polygon points="12,2 15,9 22,12 15,15 12,22 9,15 2,12 9,9" />
        </svg>
      `;
    }
    el.innerHTML = svgContent;
    container.appendChild(el);
  });
}

function randomizeBackgroundDecorations() {
  const count = 12;
  const items = [];
  
  for (let i = 0; i < count; i++) {
    items.push({
      left: `${Math.floor(Math.random() * 700) + 50}px`,
      top: `${Math.floor(Math.random() * 1050) + 50}px`,
      size: `${Math.floor(Math.random() * 40) + 15}px`,
      opacity: (Math.random() * 0.16 + 0.04).toFixed(2),
      rotation: Math.floor(Math.random() * 360)
    });
  }
  
  globalSettings.bgDecorItems = items;
  applyBackgroundDecorations();
}

// --- PREMIUM DRAG & DROP LAYOUT SWAP ---
function enableDragAndDrop() {
  const cards = document.querySelectorAll(".info-card-glass, .thermometer-container, .map-container");
  
  cards.forEach(card => {
    card.setAttribute("draggable", "true");
    
    // Dynamically toggle draggable when mouse is over interactive components to guarantee click propagation
    const interactives = card.querySelectorAll(".editable-icon-wrapper, [contenteditable='true'], button, input, select");
    interactives.forEach(el => {
      el.addEventListener("mouseenter", () => {
        card.setAttribute("draggable", "false");
      });
      el.addEventListener("mouseleave", () => {
        card.setAttribute("draggable", "true");
      });
    });

    card.addEventListener("dragstart", (e) => {
      // If user drags text or editable icons, ignore drag starts so clicks register cleanly
      if (e.target.closest(".editable-icon-wrapper") || e.target.closest("button") || e.target.closest("input") || e.target.closest("[contenteditable='true']")) {
        e.preventDefault();
        return;
      }
      e.dataTransfer.effectAllowed = "move";
      card.classList.add("dragging");
      window.draggedElement = card;
    });
    
    card.addEventListener("dragover", (e) => {
      e.preventDefault();
      card.classList.add("drag-over");
    });
    
    card.addEventListener("dragleave", () => {
      card.classList.remove("drag-over");
    });
    
    card.addEventListener("drop", (e) => {
      e.preventDefault();
      card.classList.remove("drag-over");
      
      const dragged = window.draggedElement;
      if (dragged && dragged !== card) {
        swapNodes(dragged, card);
      }
    });
    
    card.addEventListener("dragend", () => {
      card.classList.remove("dragging");
      window.draggedElement = null;
    });
  });
}

function swapNodes(nodeA, nodeB) {
  const parentA = nodeA.parentNode;
  const siblingA = nodeA.nextSibling === nodeB ? nodeA : nodeA.nextSibling;

  // Move nodeA before nodeB
  nodeB.parentNode.insertBefore(nodeA, nodeB);

  // Move nodeB before nodeA's original sibling
  if (siblingA) {
    parentA.insertBefore(nodeB, siblingA);
  } else {
    parentA.appendChild(nodeB);
  }
}

// --- PREMIUM INTERACTIVE RICH TEXT FORMATTER ---
function initRichTextFormatter() {
  const toolbar = document.getElementById("text-format-toolbar");
  if (!toolbar) return;

  const btnBold = document.getElementById("btn-format-bold");
  const btnItalic = document.getElementById("btn-format-italic");
  const btnColor = document.getElementById("btn-format-color");
  const btnSize = document.getElementById("btn-format-size");

  // Selection change listener to position floating formatting toolbar
  document.addEventListener("selectionchange", () => {
    const selection = window.getSelection();
    if (selection.rangeCount > 0 && !selection.isCollapsed) {
      const range = selection.getRangeAt(0);
      const infographic = document.getElementById("infographic-element");
      
      // Only show toolbar if selection is inside infographic container
      if (infographic && infographic.contains(range.commonAncestorContainer)) {
        const rect = range.getBoundingClientRect();
        toolbar.style.display = "flex";
        toolbar.style.left = `${rect.left + window.scrollX + (rect.width / 2) - (toolbar.offsetWidth / 2)}px`;
        toolbar.style.top = `${rect.top + window.scrollY - toolbar.offsetHeight - 8}px`;
        return;
      }
    }
    // Delay hiding slightly to allow clicks to register
    setTimeout(() => {
      const selectionCheck = window.getSelection();
      if (selectionCheck.isCollapsed) {
        toolbar.style.display = "none";
      }
    }, 150);
  });

  // Event listeners for formatting actions
  btnBold.addEventListener("mousedown", (e) => {
    e.preventDefault(); // Prevent losing text selection focus
    document.execCommand("bold", false, null);
  });

  btnItalic.addEventListener("mousedown", (e) => {
    e.preventDefault();
    document.execCommand("italic", false, null);
  });

  btnColor.addEventListener("change", (e) => {
    document.execCommand("foreColor", false, e.target.value);
  });

  btnSize.addEventListener("change", (e) => {
    if (e.target.value) {
      document.execCommand("fontSize", false, e.target.value);
      e.target.value = ""; // Reset dropdown selection
    }
  });
}



