// =============================================================================
// === EKSPOR GRAFIK & CHART STUDIO ENGINE (FORMAT GAMBAR PNG & CLIPBOARD COPY) ===
// =============================================================================

function svgToPngBlob(svgStr, width = 1400, height = 880) {
  return new Promise((resolve) => {
    try {
      let cleanSvg = (svgStr || "").trim();
      if (!cleanSvg.startsWith("<svg")) {
        // Find first <svg
        const idx = cleanSvg.indexOf("<svg");
        if (idx !== -1) cleanSvg = cleanSvg.substring(idx);
      }
      if (!cleanSvg.includes('xmlns="http://www.w3.org/2000/svg"')) {
        cleanSvg = cleanSvg.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
      }

      const svgDataUri = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(cleanSvg);
      const img = new Image();
      img.onload = function() {
        try {
          const canvas = document.createElement("canvas");
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext("2d");
          ctx.fillStyle = "#ffffff";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          canvas.toBlob(function(pngBlob) {
            resolve(pngBlob);
          }, "image/png", 1.0);
        } catch(err) {
          console.error("Canvas rasterize error:", err);
          resolve(null);
        }
      };
      img.onerror = function(err) {
        console.error("Image decode error on SVG:", err);
        resolve(null);
      };
      img.src = svgDataUri;
    } catch(e) {
      console.error("svgToPngBlob error:", e);
      resolve(null);
    }
  });
}

// --- CHART VARIABLE MANIFEST & KODE GAMBAR HELPER (G01_1 s.d. G07_2) ---
function getChartVariableManifest(distIdx = null) {
  const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
  const d = (districtsData && districtsData[targetIdx]) || { nama: "KECAMATAN", nama_proper: "Kecamatan" };
  const distName = (d.nama_proper || d.nama || "Kecamatan");
  
  const manifest = [];
  let counter = 1;

  for (let b = 1; b <= 7; b++) {
    const babInfo = BAB_TITLES[b] || { ind: `Bab ${b}`, eng: `Chapter ${b}` };
    for (let c = 1; c <= 2; c++) {
      const code = `G0${b}_${c}`;
      const fileName = `${code}.png`;
      const cfg = (chartConfigs[b] && chartConfigs[b][`chart${c}`]) || {};
      
      let metricKey = cfg.metric || "";
      let metricLabel = cfg.metricLabel || cfg.title || "Variabel Data";
      let unit = "";
      
      const metricsList = VILLAGE_METRICS_BY_BAB[b] || [];
      const foundMetric = metricsList.find(m => m.key === metricKey);
      if (foundMetric) {
        metricLabel = foundMetric.label;
        unit = foundMetric.unit;
      }
      
      const chartTypeMap = {
        bar: "Bar Chart (Vertikal)",
        hbar: "H-Bar Chart (Horizontal)",
        donut: "Donut / Pie Chart",
        line: "Line Chart (Garis & Area)",
        radar: "Radar Chart (Jaring Laba-laba)",
        lollipop: "Lollipop Chart (Batang Pin)"
      };
      const typeLabel = chartTypeMap[cfg.type] || (cfg.type ? `${cfg.type.toUpperCase()} Chart` : "Bar Chart");

      manifest.push({
        no: counter++,
        code: code,
        filename: fileName,
        bab: b,
        babTitle: babInfo.ind,
        babTitleEng: babInfo.eng,
        chartNum: c,
        metricKey: metricKey,
        variable: metricLabel,
        type: typeLabel,
        unit: unit || "-",
        kecamatan: distName
      });
    }
  }
  return manifest;
}

function generateChartManifestText(distIdx = null) {
  const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
  const d = (districtsData && districtsData[targetIdx]) || { nama: "KECAMATAN", nama_proper: "Kecamatan" };
  const distName = (d.nama || "KECAMATAN").toUpperCase();
  const manifest = getChartVariableManifest(targetIdx);

  let out = `========================================================================================\n`;
  out += `DAFTAR KODE GAMBAR GRAFIK PUBLIKASI KECAMATAN DALAM ANGKA (KCDA)\n`;
  out += `BADAN PUSAT STATISTIK KABUPATEN PANDEGLANG\n`;
  out += `Wilayah Kecamatan : KECAMATAN ${distName}\n`;
  out += `Jumlah Grafik     : 14 Gambar Grafik (G01_1 s.d. G07_2)\n`;
  out += `Tanggal Ekspor    : ${new Date().toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}\n`;
  out += `========================================================================================\n\n`;

  out += `+----+-------------+------------+-------+----------------------------------------+---------------------------------------+--------------------------+----------+\n`;
  out += `| No | Kode Gambar | Nama File  | Bab   | Judul Bab KCDA                         | Variabel / Indikator Data             | Tipe Visualisasi         | Satuan   |\n`;
  out += `+----+-------------+------------+-------+----------------------------------------+---------------------------------------+--------------------------+----------+\n`;

  manifest.forEach(item => {
    const noStr = String(item.no).padStart(2, ' ');
    const codeStr = item.code.padEnd(11, ' ');
    const fileStr = item.filename.padEnd(10, ' ');
    const babStr = `Bab ${item.bab}`.padEnd(5, ' ');
    const babTitleStr = (item.babTitle.length > 38 ? item.babTitle.substr(0, 35) + '...' : item.babTitle).padEnd(38, ' ');
    const varStr = (item.variable.length > 37 ? item.variable.substr(0, 34) + '...' : item.variable).padEnd(37, ' ');
    const typeStr = (item.type.length > 24 ? item.type.substr(0, 21) + '...' : item.type).padEnd(24, ' ');
    const unitStr = (item.unit.length > 8 ? item.unit.substr(0, 8) : item.unit).padEnd(8, ' ');

    out += `| ${noStr} | ${codeStr} | ${fileStr} | ${babStr} | ${babTitleStr} | ${varStr} | ${typeStr} | ${unitStr} |\n`;
  });

  out += `+----+-------------+------------+-------+----------------------------------------+---------------------------------------+--------------------------+----------+\n\n`;
  out += `Catatan Penggunaan:\n`;
  out += `1. Format penamaan berkas gambar: G{2 Digit Nomor Bab}_{Nomor Urut Grafik}.png\n`;
  out += `   Contoh: G01_1.png = Grafik Bab 1 nomor urut 1, G05_2.png = Grafik Bab 5 nomor urut 2.\n`;
  out += `2. Seluruh gambar grafik dirender tanpa judul di dalam kanvas SVG/PNG agar lebih bersih & fleksibel disisipkan ke Word/InDesign.\n`;
  out += `3. Gunakan daftar di atas untuk mencocokkan kode gambar dengan variabel yang diwakili saat penyusunan naskah publikasi KCDA.\n`;

  return out;
}

function generateChartManifestExcelBlob(distIdx = null) {
  if (typeof XLSX === "undefined") return null;

  const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
  const d = (districtsData && districtsData[targetIdx]) || { nama: "KECAMATAN", nama_proper: "Kecamatan" };
  const distName = (d.nama || "KECAMATAN").toUpperCase();
  const manifest = getChartVariableManifest(targetIdx);

  const rows = [
    ["DAFTAR KODE GAMBAR GRAFIK KCDA - BPS KABUPATEN PANDEGLANG"],
    [`Kecamatan: ${distName} | Jumlah Grafik: 14 Berkas (G01_1 s.d. G07_2)`],
    []
  ];

  const headers = [
    "No",
    "Kode Gambar",
    "Nama File PNG",
    "Bab",
    "Judul Bab (Indonesia)",
    "Judul Bab (English)",
    "Grafik Ke-",
    "Nama Variabel / Indikator Data",
    "Tipe Visualisasi",
    "Satuan Data",
    "Kecamatan"
  ];
  rows.push(headers);

  manifest.forEach(item => {
    rows.push([
      item.no,
      item.code,
      item.filename,
      `Bab ${item.bab}`,
      item.babTitle,
      item.babTitleEng,
      `Grafik ${item.chartNum}`,
      item.variable,
      item.type,
      item.unit,
      distName
    ]);
  });

  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet(rows);

  ws['!cols'] = [
    { wch: 6 },
    { wch: 14 },
    { wch: 16 },
    { wch: 10 },
    { wch: 38 },
    { wch: 38 },
    { wch: 12 },
    { wch: 42 },
    { wch: 26 },
    { wch: 14 },
    { wch: 18 }
  ];

  XLSX.utils.book_append_sheet(wb, ws, "Daftar_Kode_Grafik");

  const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
  return new Blob([wbout], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
}

function downloadChartManifest(distIdx = null) {
  const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
  const d = (districtsData && districtsData[targetIdx]) || { nama: "KECAMATAN" };
  const distName = (d.nama || "KECAMATAN").toUpperCase();

  const excelBlob = generateChartManifestExcelBlob(targetIdx);
  if (excelBlob) {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(excelBlob);
    a.download = `DAFTAR_KODE_GRAFIK_KCDA_${distName}.xlsx`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  const textContent = generateChartManifestText(targetIdx);
  const textBlob = new Blob([textContent], { type: "text/plain;charset=utf-8" });
  const aText = document.createElement("a");
  aText.href = URL.createObjectURL(textBlob);
  aText.download = `DAFTAR_KODE_GRAFIK_KCDA_${distName}.txt`;
  document.body.appendChild(aText);
  aText.click();
  document.body.removeChild(aText);

  showToast("success", "Daftar Kode Grafik Diunduh!", `Berkas Excel (.xlsx) dan Teks (.txt) daftar kode gambar G01_1 s.d G07_2 (${distName}) berhasil diunduh.`);
}

async function copyChartImageToClipboard(chartNum, babNum, distIdx = null) {
  try {
    const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
    const d = districtsData[targetIdx] || {};
    const cfg = chartConfigs[babNum] && chartConfigs[babNum][`chart${chartNum}`];
    if (!cfg) return;

    const chartCode = `G0${babNum}_${chartNum}`;
    const varLabel = cfg.metricLabel || cfg.title || "Grafik Data";

    showToast("info", "Menyiapkan Gambar...", `Sedang merender ${chartCode} (${varLabel}) untuk clipboard.`);

    const svgHtml = renderCustomChartSVG(cfg, d, babNum, 800, 500);
    const pngBlob = await svgToPngBlob(svgHtml, 1600, 1000);
    if (!pngBlob) {
      showToast("error", "Gagal Memproses Gambar", "Tidak dapat merender gambar.");
      return;
    }

    if (navigator.clipboard && window.ClipboardItem) {
      await navigator.clipboard.write([
        new ClipboardItem({ "image/png": pngBlob })
      ]);
      showToast("success", `Gambar ${chartCode} Tersalin ke Clipboard! 📋`, `Variabel: ${varLabel}. Silakan buka Microsoft Word atau InDesign, lalu tekan Ctrl + V (Paste).`, 4000);
    } else {
      const a = document.createElement("a");
      a.download = `${chartCode}.png`;
      a.href = URL.createObjectURL(pngBlob);
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      showToast("info", `Gambar ${chartCode}.png Diunduh`, `Variabel: ${varLabel}. Berkas gambar berhasil diunduh.`);
    }
  } catch(err) {
    console.error("Clipboard copy error:", err);
    showToast("error", "Gagal Menyalin", "Gunakan tombol Unduh PNG untuk menyisipkan ke Word/InDesign.");
  }
}

async function exportSingleChartPNG(chartNum, babNum, distIdx = null) {
  const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
  const d = districtsData[targetIdx] || {};
  const distName = (d.nama || "Kecamatan").toUpperCase();
  const cfg = chartConfigs[babNum] && chartConfigs[babNum][`chart${chartNum}`];
  if (!cfg) return;

  const chartCode = `G0${babNum}_${chartNum}`;
  const fileName = `${chartCode}.png`;
  const varLabel = cfg.metricLabel || cfg.title || "Grafik Data";

  showToast("info", "Merender Gambar PNG...", `Sedang menyiapkan berkas ${fileName} (${varLabel}).`);

  const svgHtml = renderCustomChartSVG(cfg, d, babNum, 800, 500);
  const pngBlob = await svgToPngBlob(svgHtml, 1600, 1000);
  if (!pngBlob) {
    showToast("error", "Gagal Merender Gambar", "Terjadi kesalahan saat memproses gambar grafik.");
    return;
  }

  const a = document.createElement("a");
  a.download = fileName;
  a.href = URL.createObjectURL(pngBlob);
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  showToast("success", `Gambar ${fileName} Terunduh!`, `Kode: ${chartCode} | Variabel: ${varLabel} (Kecamatan ${distName})`);
}

async function exportActiveDistrictChartsZIP() {
  if (typeof JSZip === "undefined") {
    showToast("error", "Library JSZip Belum Siap", "Silakan periksa koneksi internet.");
    return;
  }

  const d = districtsData[activeIndex] || {};
  const distName = (d.nama || "Kecamatan").toUpperCase();
  const zip = new JSZip();
  const folder = zip.folder(`Grafik_${distName}`);

  showToast("info", "Memproses 14 Gambar PNG...", `Sedang merender berkas gambar G01_1 s.d. G07_2 untuk Kecamatan ${distName}.`);

  for (let b = 1; b <= 7; b++) {
    for (let c = 1; c <= 2; c++) {
      const cfg = chartConfigs[b] && chartConfigs[b][`chart${c}`];
      if (cfg) {
        const svgStr = renderCustomChartSVG(cfg, d, b, 800, 500);
        const pngBlob = await svgToPngBlob(svgStr, 1600, 1000);
        const fileName = `G0${b}_${c}.png`;
        if (pngBlob) {
          folder.file(fileName, pngBlob);
        } else {
          folder.file(`G0${b}_${c}.svg`, svgStr);
        }
      }
    }
  }

  const manifestText = generateChartManifestText(activeIndex);
  folder.file("DAFTAR_KODE_GRAFIK_KCDA.txt", manifestText);

  const manifestExcelBlob = generateChartManifestExcelBlob(activeIndex);
  if (manifestExcelBlob) {
    folder.file("DAFTAR_KODE_GRAFIK_KCDA.xlsx", manifestExcelBlob);
  }

  const content = await zip.generateAsync({ type: "blob" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(content);
  a.download = `Paket_14_Grafik_${distName}_(G01_1_sd_G07_2).zip`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  showToast("success", "Paket 14 Gambar Grafik PNG Siap!", `Arsip ZIP Kecamatan ${distName} (G01_1 s.d. G07_2 + Daftar Kode Excel/TXT) berhasil diunduh.`);
}

async function exportAll35DistrictsChartsZIP() {
  if (typeof JSZip === "undefined") {
    showToast("error", "Library JSZip Belum Siap", "Silakan periksa koneksi internet.");
    return;
  }

  if (!districtsData || districtsData.length === 0) {
    showToast("error", "Data Belum Tersedia", "Tidak ada basis data kecamatan.");
    return;
  }

  showToast("info", "Memulai Ekspor Massal 490 Gambar PNG...", "Sedang merender 490 file gambar grafik (G01_1 s.d. G07_2) untuk seluruh 35 kecamatan. Harap tunggu sebentar.");

  const zip = new JSZip();
  const rootFolder = zip.folder("KOMPILASI_GRAFIK_KCDA_35_KECAMATAN");

  const allManifestRows = [
    ["DAFTAR KODE & VARIABEL GRAFIK KCDA - 35 KECAMATAN KABUPATEN PANDEGLANG"],
    ["Kompilasi 490 Gambar Grafik (14 Grafik per Kecamatan x 35 Kecamatan)"],
    []
  ];
  const manifestHeaders = [
    "No",
    "Kode Kecamatan",
    "Nama Kecamatan",
    "Kode Gambar",
    "Nama File PNG",
    "Bab",
    "Judul Bab (Indonesia)",
    "Judul Bab (English)",
    "Grafik Ke-",
    "Nama Variabel / Indikator Data",
    "Tipe Visualisasi",
    "Satuan Data"
  ];
  allManifestRows.push(manifestHeaders);

  let globalCounter = 1;

  for (let dIdx = 0; dIdx < districtsData.length; dIdx++) {
    const d = districtsData[dIdx];
    const kecCode = String(dIdx + 1).padStart(2, '0');
    const distNameUpper = (d.nama || `Kecamatan_${dIdx+1}`).toUpperCase();
    const folderName = `${kecCode}_${distNameUpper}`;
    const distFolder = rootFolder.folder(folderName);

    const distManifest = getChartVariableManifest(dIdx);
    distManifest.forEach(item => {
      allManifestRows.push([
        globalCounter++,
        kecCode,
        distNameUpper,
        item.code,
        item.filename,
        `Bab ${item.bab}`,
        item.babTitle,
        item.babTitleEng,
        `Grafik ${item.chartNum}`,
        item.variable,
        item.type,
        item.unit
      ]);
    });

    for (let b = 1; b <= 7; b++) {
      for (let c = 1; c <= 2; c++) {
        const cfg = chartConfigs[b] && chartConfigs[b][`chart${c}`];
        if (cfg) {
          const svgStr = renderCustomChartSVG(cfg, d, b, 700, 440);
          const pngBlob = await svgToPngBlob(svgStr, 1400, 880);
          const fileName = `G0${b}_${c}.png`;
          if (pngBlob) {
            distFolder.file(fileName, pngBlob);
          } else {
            distFolder.file(`G0${b}_${c}.svg`, svgStr);
          }
        }
      }
    }

    const distTxt = generateChartManifestText(dIdx);
    distFolder.file("DAFTAR_KODE_GRAFIK_KCDA.txt", distTxt);
  }

  if (typeof XLSX !== "undefined") {
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet(allManifestRows);
    ws['!cols'] = [
      { wch: 6 },
      { wch: 10 },
      { wch: 20 },
      { wch: 14 },
      { wch: 16 },
      { wch: 10 },
      { wch: 38 },
      { wch: 38 },
      { wch: 12 },
      { wch: 42 },
      { wch: 26 },
      { wch: 14 }
    ];
    XLSX.utils.book_append_sheet(wb, ws, "Daftar_490_Grafik_35_Kec");
    const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    rootFolder.file("DAFTAR_KODE_GRAFIK_35_KECAMATAN.xlsx", new Blob([wbout], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }));
  }

  let rootTxt = `DAFTAR KODE GAMBAR GRAFIK 35 KECAMATAN KABUPATEN PANDEGLANG (490 GRAFIK)\n`;
  rootTxt += `Format Penamaan: G01_1.png s.d. G07_2.png di setiap folder kecamatan.\n\n`;
  const defaultManifest = getChartVariableManifest(activeIndex);
  defaultManifest.forEach(m => {
    rootTxt += `[${m.code}] ${m.filename} -> Bab ${m.bab} (${m.babTitle}): ${m.variable} [${m.type}] [Satuan: ${m.unit}]\n`;
  });
  rootFolder.file("DAFTAR_KODE_GRAFIK_SEMUA_KECAMATAN.txt", rootTxt);

  const content = await zip.generateAsync({ type: "blob" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(content);
  a.download = `KOMPILASI_490_GRAFIK_KCDA_35_KECAMATAN_(G01_1_sd_G07_2).zip`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  showToast("success", "490 Gambar Grafik PNG Berhasil Diekspor!", "Seluruh grafik PNG G01_1 s.d. G07_2 untuk 35 kecamatan + Master Manifest Excel/TXT telah berhasil dikemas dalam format ZIP.");
}

