  a.href = URL.createObjectURL(blob);
  a.download = `KOMPILASI_INTERPRETASI_KCDA_35_KECAMATAN.doc`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  showToast("success", "Kompilasi 35 Naskah Siap!", "Buku kompilasi naskah Word 35 kecamatan berhasil diunduh.");
