// Helper: Bersihkan tag HTML menjadi teks polos berparagraf rapi
function cleanHtmlToText(html) {
  if (!html) return "";
  return html
    .replace(/km\uFFFD/g, "km²")
    .replace(/km\u00B2/g, "km²")
    .replace(/\uFFFD/g, "–")
    .replace(/<\/p>/gi, "\n\n")
    .replace(/<\/div>/gi, "\n\n")
    .replace(/<\/h[1-6]>/gi, "\n\n")
    .replace(/<br\s*[\/]?>/gi, "\n")
    .replace(/<[^>]+>/gi, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

// Helper: Ekstrak daftar paragraf terpisah (array of string) dari HTML atau teks narasi
function extractParagraphs(htmlOrText) {
  if (!htmlOrText) return [];
  const clean = cleanHtmlToText(htmlOrText);
  return clean
    .split(/\n+/)
    .map(p => p.trim())
    .filter(p => p.length > 0 && !p.startsWith("===") && !p.startsWith("---"));
}

const BAB_TITLES_PLAIN = {
  1: "Geografi & Iklim",
  2: "Pemerintahan",
  3: "Kependudukan",
  4: "Sosial & Kesra",
  5: "Pertanian",
  6: "Pariwisata & Transportasi",
  7: "Perbankan & Perdagangan"
};

// Ekspor Naskah Interpretasi Excel Bilingual (Indo & Inggris) Kolom Per Paragraf untuk 1 Kecamatan Aktif
function exportInterpretasiExcel(distIdx = null) {
  if (!districtsData || districtsData.length === 0) {
    showToast("error", "Data Belum Tersedia", "Mohon unggah file Excel data kecamatan terlebih dahulu.");
    return;
  }
  if (typeof XLSX === "undefined") {
    showToast("error", "Library SheetJS Belum Siap", "Silakan periksa koneksi internet.");
    return;
  }

  const targetIdx = (distIdx !== null && distIdx !== undefined) ? distIdx : activeIndex;
  const d = districtsData[targetIdx] || {};
  const distName = (d.nama_proper || d.nama || "Kecamatan").toUpperCase();
  const distCode = d.kode_kec || (targetIdx + 1);

  const wb = XLSX.utils.book_new();

  // 1. Sheet Semua_Bab (Bab 1 s.d. 7 dalam baris terpisah dengan kolom per-paragraf)
  const masterRows = [];
  const maxParasAcrossBabs = 6;
  const masterHeaders = ["No", "Kode Kecamatan", "Nama Kecamatan", "Bab", "Judul Bab"];
  for (let p = 1; p <= maxParasAcrossBabs; p++) {
    masterHeaders.push(`Paragraf ${p} (Bahasa Indonesia)`);
    masterHeaders.push(`Paragraph ${p} (English)`);
  }

  for (let b = 1; b <= 7; b++) {
    const dataId = generateComprehensiveInterpretasi(targetIdx, String(b), "formal", "id");
    const dataEn = generateComprehensiveInterpretasi(targetIdx, String(b), "formal", "en");
    const parasId = extractParagraphs(dataId.narrativeHtml);
    const parasEn = extractParagraphs(dataEn.narrativeHtml);

    const rowObj = {
      "No": b,
      "Kode Kecamatan": distCode,
      "Nama Kecamatan": `KECAMATAN ${distName}`,
      "Bab": `Bab ${b}`,
      "Judul Bab": BAB_TITLES_PLAIN[b] || `Bab ${b}`
    };

    for (let p = 1; p <= maxParasAcrossBabs; p++) {
      rowObj[`Paragraf ${p} (Bahasa Indonesia)`] = parasId[p - 1] || "";
      rowObj[`Paragraph ${p} (English)`] = parasEn[p - 1] || "";
    }

    masterRows.push(rowObj);
  }

  const wsMaster = XLSX.utils.json_to_sheet(masterRows, { header: masterHeaders });
  const masterCols = [{ wch: 6 }, { wch: 15 }, { wch: 24 }, { wch: 10 }, { wch: 28 }];
  for (let p = 1; p <= maxParasAcrossBabs; p++) {
    masterCols.push({ wch: 75 });
    masterCols.push({ wch: 75 });
  }
  wsMaster['!cols'] = masterCols;
  XLSX.utils.book_append_sheet(wb, wsMaster, "Semua_Bab");

  // 2. Buat Lembar Kerja Spesifik Per Bab (Bab1_Geografi s.d. Bab7_Perdagangan)
  const sheetNames = {
    1: "Bab1_Geografi",
    2: "Bab2_Pemerintahan",
    3: "Bab3_Kependudukan",
    4: "Bab4_Sosial_Kesra",
    5: "Bab5_Pertanian",
    6: "Bab6_Transportasi",
    7: "Bab7_Perdagangan"
  };

  for (let b = 1; b <= 7; b++) {
    const dataId = generateComprehensiveInterpretasi(targetIdx, String(b), "formal", "id");
    const dataEn = generateComprehensiveInterpretasi(targetIdx, String(b), "formal", "en");
    const parasId = extractParagraphs(dataId.narrativeHtml);
    const parasEn = extractParagraphs(dataEn.narrativeHtml);
    const pCount = Math.max(parasId.length, parasEn.length, 1);

    const babHeaders = ["No", "Kode Kecamatan", "Nama Kecamatan", "Bab", "Judul Bab"];
    const rowBab = {
      "No": 1,
      "Kode Kecamatan": distCode,
      "Nama Kecamatan": `KECAMATAN ${distName}`,
      "Bab": `Bab ${b}`,
      "Judul Bab": BAB_TITLES_PLAIN[b] || `Bab ${b}`
    };

    for (let p = 1; p <= pCount; p++) {
      babHeaders.push(`Paragraf ${p} (Bahasa Indonesia)`);
      babHeaders.push(`Paragraph ${p} (English)`);
      rowBab[`Paragraf ${p} (Bahasa Indonesia)`] = parasId[p - 1] || "";
      rowBab[`Paragraph ${p} (English)`] = parasEn[p - 1] || "";
    }

    const wsBab = XLSX.utils.json_to_sheet([rowBab], { header: babHeaders });
    const bCols = [{ wch: 6 }, { wch: 15 }, { wch: 24 }, { wch: 10 }, { wch: 26 }];
    for (let p = 1; p <= pCount; p++) {
      bCols.push({ wch: 75 });
      bCols.push({ wch: 75 });
    }
    wsBab['!cols'] = bCols;
    XLSX.utils.book_append_sheet(wb, wsBab, sheetNames[b]);
  }

  // 3. Tambahkan Sheet Ringkasan Eksekutif
  const dataFullId = generateComprehensiveInterpretasi(targetIdx, "full", "formal", "id");
  const dataFullEn = generateComprehensiveInterpretasi(targetIdx, "full", "formal", "en");
  const execParasId = extractParagraphs(dataFullId.narrativeHtml);
  const execParasEn = extractParagraphs(dataFullEn.narrativeHtml);
  const execCount = Math.max(execParasId.length, execParasEn.length, 7);

  const execHeaders = ["No", "Kode Kecamatan", "Nama Kecamatan"];
  const execRow = {
    "No": 1,
    "Kode Kecamatan": distCode,
    "Nama Kecamatan": `KECAMATAN ${distName}`
  };
  for (let p = 1; p <= execCount; p++) {
    execHeaders.push(`Paragraf ${p} (Bahasa Indonesia)`);
    execHeaders.push(`Paragraph ${p} (English)`);
    execRow[`Paragraf ${p} (Bahasa Indonesia)`] = execParasId[p - 1] || "";
    execRow[`Paragraph ${p} (English)`] = execParasEn[p - 1] || "";
  }
  const wsExec = XLSX.utils.json_to_sheet([execRow], { header: execHeaders });
  const execCols = [{ wch: 6 }, { wch: 15 }, { wch: 24 }];
  for (let p = 1; p <= execCount; p++) {
    execCols.push({ wch: 75 });
    execCols.push({ wch: 75 });
  }
  wsExec['!cols'] = execCols;
  XLSX.utils.book_append_sheet(wb, wsExec, "Ringkasan_Eksekutif");

  const fileName = `Interpretasi_KCDA_${distName}_Bilingual_Per_Paragraf_Bab1_7.xlsx`;
  XLSX.writeFile(wb, fileName);
  showToast("success", "Excel Interpretasi Terunduh! 📗", `Naskah interpretasi ${distName} (kolom terpisah per paragraf Indo & Inggris) berhasil diunduh.`);
}

// Ekspor Naskah Interpretasi Excel Kompilasi 35 Kecamatan (Bab 1 s.d. 7 Bilingual Kolom Per Paragraf)
function exportAll35InterpretasiExcel() {
  if (!districtsData || districtsData.length === 0) {
    showToast("error", "Data Belum Tersedia", "Mohon unggah file Excel data kecamatan terlebih dahulu.");
    return;
  }
  if (typeof XLSX === "undefined") {
    showToast("error", "Library SheetJS Belum Siap", "Silakan periksa koneksi internet.");
    return;
  }

  showToast("info", "Memproses Excel 35 Kecamatan...", "Menyusun naskah narasi bilingual Bab 1 s.d. 7 kolom per paragraf untuk 35 kecamatan.");

  const wb = XLSX.utils.book_new();

  // Data penampung
  const masterRows = [];
  const babSheetsData = { 1: [], 2: [], 3: [], 4: [], 5: [], 6: [], 7: [] };
  const babMaxParas = { 1: 4, 2: 4, 3: 5, 4: 6, 5: 3, 6: 2, 7: 3 };
  const execRows = [];

  // Hitung jumlah paragraf aktual jika ada yang lebih banyak
  districtsData.forEach((d, idx) => {
    for (let b = 1; b <= 7; b++) {
      const dataId = generateComprehensiveInterpretasi(idx, String(b), "formal", "id");
      const dataEn = generateComprehensiveInterpretasi(idx, String(b), "formal", "en");
      const pIdLen = extractParagraphs(dataId.narrativeHtml).length;
      const pEnLen = extractParagraphs(dataEn.narrativeHtml).length;
      babMaxParas[b] = Math.max(babMaxParas[b], pIdLen, pEnLen);
    }
  });

  districtsData.forEach((d, idx) => {
    const distName = (d.nama_proper || d.nama || KECAMATAN_LIST[idx] || `KECAMATAN_${idx+1}`).toUpperCase();
    const distCode = d.kode_kec || (idx + 1);

    // Loop Bab 1 - 7
    for (let b = 1; b <= 7; b++) {
      const dataId = generateComprehensiveInterpretasi(idx, String(b), "formal", "id");
      const dataEn = generateComprehensiveInterpretasi(idx, String(b), "formal", "en");
      const parasId = extractParagraphs(dataId.narrativeHtml);
      const parasEn = extractParagraphs(dataEn.narrativeHtml);

      // Baris per sheet bab
      const rowBab = {
        "No": idx + 1,
        "Kode Kecamatan": distCode,
        "Nama Kecamatan": distName
      };
      for (let p = 1; p <= babMaxParas[b]; p++) {
        rowBab[`Paragraf ${p} (Bahasa Indonesia)`] = parasId[p - 1] || "";
        rowBab[`Paragraph ${p} (English)`] = parasEn[p - 1] || "";
      }
      babSheetsData[b].push(rowBab);

      // Baris master kompilasi (max 6 paragraf)
      const rowComp = {
        "No": masterRows.length + 1,
        "Kode Kecamatan": distCode,
        "Nama Kecamatan": distName,
        "Bab": `Bab ${b}`,
        "Judul Bab": BAB_TITLES_PLAIN[b] || `Bab ${b}`
      };
      for (let p = 1; p <= 6; p++) {
        rowComp[`Paragraf ${p} (Bahasa Indonesia)`] = parasId[p - 1] || "";
        rowComp[`Paragraph ${p} (English)`] = parasEn[p - 1] || "";
      }
      masterRows.push(rowComp);
    }

    // Executive Summary
    const dataFullId = generateComprehensiveInterpretasi(idx, "full", "formal", "id");
    const dataFullEn = generateComprehensiveInterpretasi(idx, "full", "formal", "en");
    const fullParasId = extractParagraphs(dataFullId.narrativeHtml);
    const fullParasEn = extractParagraphs(dataFullEn.narrativeHtml);

    const rowExec = {
      "No": idx + 1,
      "Kode Kecamatan": distCode,
      "Nama Kecamatan": distName
    };
    for (let b = 1; b <= 7; b++) {
      rowExec[`Bab ${b} ${BAB_TITLES_PLAIN[b]} (Bahasa Indonesia)`] = fullParasId[b - 1] || "";
      rowExec[`Chapter ${b} ${BAB_TITLES_PLAIN[b]} (English)`] = fullParasEn[b - 1] || "";
    }
    execRows.push(rowExec);
  });

  // 1. Buat Sheet 1 s.d. 7 (Per Bab)
  const sheetNames = {
    1: "Bab1_Geografi",
    2: "Bab2_Pemerintahan",
    3: "Bab3_Kependudukan",
    4: "Bab4_Sosial_Kesra",
    5: "Bab5_Pertanian",
    6: "Bab6_Transportasi",
    7: "Bab7_Perdagangan"
  };

  for (let b = 1; b <= 7; b++) {
    const babHeaders = ["No", "Kode Kecamatan", "Nama Kecamatan"];
    const bCols = [{ wch: 6 }, { wch: 15 }, { wch: 24 }];
    for (let p = 1; p <= babMaxParas[b]; p++) {
      babHeaders.push(`Paragraf ${p} (Bahasa Indonesia)`);
      babHeaders.push(`Paragraph ${p} (English)`);
      bCols.push({ wch: 75 });
      bCols.push({ wch: 75 });
    }

    const wsBab = XLSX.utils.json_to_sheet(babSheetsData[b], { header: babHeaders });
    wsBab['!cols'] = bCols;
    XLSX.utils.book_append_sheet(wb, wsBab, sheetNames[b]);
  }

  // 2. Buat Sheet Master Kompilasi
  const masterHeaders = ["No", "Kode Kecamatan", "Nama Kecamatan", "Bab", "Judul Bab"];
  const masterCols = [{ wch: 6 }, { wch: 15 }, { wch: 24 }, { wch: 10 }, { wch: 28 }];
  for (let p = 1; p <= 6; p++) {
    masterHeaders.push(`Paragraf ${p} (Bahasa Indonesia)`);
    masterHeaders.push(`Paragraph ${p} (English)`);
    masterCols.push({ wch: 75 });
    masterCols.push({ wch: 75 });
  }

  const wsMaster = XLSX.utils.json_to_sheet(masterRows, { header: masterHeaders });
  wsMaster['!cols'] = masterCols;
  XLSX.utils.book_append_sheet(wb, wsMaster, "Semua_Bab_Kompilasi");

  // 3. Buat Sheet Ringkasan Eksekutif
  const execHeaders = ["No", "Kode Kecamatan", "Nama Kecamatan"];
  const execCols = [{ wch: 6 }, { wch: 15 }, { wch: 24 }];
  for (let b = 1; b <= 7; b++) {
    execHeaders.push(`Bab ${b} ${BAB_TITLES_PLAIN[b]} (Bahasa Indonesia)`);
    execHeaders.push(`Chapter ${b} ${BAB_TITLES_PLAIN[b]} (English)`);
    execCols.push({ wch: 75 });
    execCols.push({ wch: 75 });
  }

  const wsExec = XLSX.utils.json_to_sheet(execRows, { header: execHeaders });
  wsExec['!cols'] = execCols;
  XLSX.utils.book_append_sheet(wb, wsExec, "Ringkasan_Eksekutif");

  const fileName = "Kompilasi_Interpretasi_KCDA_35_Kecamatan_Bilingual_Per_Paragraf_Bab1_7.xlsx";
  XLSX.writeFile(wb, fileName);
  showToast("success", "Kompilasi Excel 35 Kec Siap! 📗", `Berkas '${fileName}' (Bab 1-7 Indo & Inggris kolom per paragraf untuk 35 Kecamatan) berhasil diunduh.`);
}



