async function downloadMergePackageZIP(mode = "sample") {
  if (typeof JSZip === "undefined") {
    showToast("error", "Library JSZip Belum Siap", "Silakan tunggu beberapa saat atau periksa koneksi internet.");
    return;
  }

  const isBlank = (mode === "blank");
  const zip = new JSZip();
  const folderName = isBlank ? "TEMPLATE_KOSONG_7_FILE_MERGE_BPS" : "PAKET_7_FILE_MERGE_BPS_PANDEGLANG_2026";
  const folder = zip.folder(folderName);

  showToast("info", "Menyiapkan Paket 7 File Merge...", `Sedang mengemas 7 berkas CSV Merge (${isBlank ? 'Template Kosong' : 'Data Riil Lengkap'}) ke dalam format ZIP.`);

  for (let b = 1; b <= 7; b++) {
    const dataObj = MERGE_CSVS_DATA[b];
    if (dataObj) {
      const fName = isBlank ? dataObj.blank_filename : dataObj.filename;
      const fContent = isBlank ? dataObj.blank_csv : dataObj.raw_csv;
      folder.file(fName, fContent);
    }
  }

  const zipBlob = await zip.generateAsync({ type: "blob" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(zipBlob);
  a.download = `${folderName}.zip`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  showToast("success", "Paket Merge Berhasil Diunduh! 📦", `Berkas '${folderName}.zip' (7 File CSV BPS) siap digunakan.`);
}

function downloadSingleMergeCSV(babNum, mode = "sample") {
  const dataObj = MERGE_CSVS_DATA[babNum];
  if (!dataObj) {
    showToast("error", "Data Merge Tidak Ditemukan", `Berkas Merge Bab ${babNum} belum tersedia.`);
    return;
  }

  const isBlank = (mode === "blank");
  const fName = isBlank ? dataObj.blank_filename : dataObj.filename;
  const fContent = isBlank ? dataObj.blank_csv : dataObj.raw_csv;

  const blob = new Blob([fContent], { type: "text/csv;charset=latin1" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = fName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  showToast("success", "File CSV Terunduh", `Berkas '${fName}' berhasil diunduh.`);
}

function downloadMasterKCDAExcel(mode = "sample") {
  if (typeof XLSX === "undefined") {
    showToast("error", "Library SheetJS Belum Siap", "Tidak dapat membuat file Excel.");
    return;
  }

  const isBlank = (mode === "blank");
  const wb = XLSX.utils.book_new();

  // Sheet Panduan
  const panduanData = [
    ["PETUNJUK PENGISIAN MASTER DATA KCDA 7 BAB (master_kcda.xlsx) - BPS KABUPATEN PANDEGLANG"],
    [""],
    ["1. Berkas ini memuat 7 Lembar Kerja (Sheet) data statistik Kecamatan Dalam Angka (KCDA):"],
    ["   - Bab1_Geografi: Data letak geografis, batas wilayah, luas, ketinggian, dan jarak."],
    ["   - Bab2_Pemerintahan: Data jumlah RT/RW, komposisi PNS menurut gender, pendidikan & golongan."],
    ["   - Bab3_Kependudukan: Data jumlah penduduk, kepadatan, rasio jenis kelamin, dan sebaran umur."],
    ["   - Bab4_Sosial: Data fasilitas pendidikan, jumlah guru, rasio murid-guru, dan status gizi balita."],
    ["   - Bab5_Pertanian: Data komoditas sayuran, biofarma, dan produksi buah tahunan."],
    ["   - Bab6_Ekonomi: Data sarana akomodasi wisata, pos, ekspedisi, dan industri."],
    ["   - Bab7_Keuangan: Data perbankan, koperasi, dan sarana perdagangan."],
    [""],
    ["2. Jangan mengubah urutan dan penamaan lembar kerja (Sheet) agar integrasi data berjalan otomatis."],
    ["3. Kolom 'kecamatan' merupakan kunci penghubung ke seluruh modul infografis dan narasi interpretasi."],
    ["4. Unggah kembali berkas ini pada menu 'Data Excel KCDA' atau Dashboard aplikasi SMARTGRAF KCDA."]
  ];
  const wsPanduan = XLSX.utils.aoa_to_sheet(panduanData);
  XLSX.utils.book_append_sheet(wb, wsPanduan, "Panduan");

  // Sheets Bab1 s.d. Bab7
  const sheetDefs = [
    { key: "Bab1_Geografi", babNum: 1 },
    { key: "Bab2_Pemerintahan", babNum: 2 },
    { key: "Bab3_Kependudukan", babNum: 3 },
    { key: "Bab4_Sosial", babNum: 4 },
    { key: "Bab5_Pertanian", babNum: 5 },
    { key: "Bab6_Ekonomi", babNum: 6 },
    { key: "Bab7_Keuangan", babNum: 7 }
  ];

  sheetDefs.forEach(s => {
    const rows = [];
    districtsData.forEach((d, idx) => {
      const raw = (d.rawMaster && d.rawMaster[s.key]) || (d[`bab${s.babNum}`]) || {};
      const rowObj = {};
      
      // Collect all keys
      Object.keys(raw).forEach(k => {
        if (k.toLowerCase() === "kecamatan") {
          rowObj[k] = d.nama_proper || d.nama;
        } else {
          rowObj[k] = isBlank ? "" : raw[k];
        }
      });
      if (!rowObj.kecamatan) rowObj.kecamatan = d.nama_proper || d.nama;
      rows.push(rowObj);
    });

    const ws = XLSX.utils.json_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, s.key);
  });

  const fileName = isBlank ? "template_master_kcda_7bab_format_kosong.xlsx" : "master_kcda_pandeglang_7bab.xlsx";
  XLSX.writeFile(wb, fileName);
  showToast("success", "Master Excel Terunduh! 📊", `Berkas '${fileName}' (7 Sheets Terpadu) berhasil diunduh.`);
}

function downloadActiveMemoryBackupExcel() {
  if (typeof XLSX === "undefined") {
    showToast("error", "Library SheetJS Belum Siap", "Tidak dapat membuat file Excel.");
    return;
  }

  const wb = XLSX.utils.book_new();

  // Panduan Backup
  const infoData = [
    ["CADANGAN DATA AKTIF (LIVE MEMORY BACKUP) - SMARTGRAF KCDA"],
    ["Waktu Pencadangan: " + new Date().toLocaleString('id-ID')],
    ["Jumlah Wilayah: " + districtsData.length + " Kecamatan"],
    [""],
    ["Berkas ini memuat seluruh data aktif yang saat ini dimuat atau diedit di dalam memori browser."]
  ];
  const wsInfo = XLSX.utils.aoa_to_sheet(infoData);
  XLSX.utils.book_append_sheet(wb, wsInfo, "Info_Cadangan");

  const sheetDefs = [
    { key: "Bab1_Geografi", babNum: 1 },
    { key: "Bab2_Pemerintahan", babNum: 2 },
    { key: "Bab3_Kependudukan", babNum: 3 },
    { key: "Bab4_Sosial", babNum: 4 },
    { key: "Bab5_Pertanian", babNum: 5 },
    { key: "Bab6_Ekonomi", babNum: 6 },
    { key: "Bab7_Keuangan", babNum: 7 }
  ];

  sheetDefs.forEach(s => {
    const rows = [];
    districtsData.forEach((d) => {
      const raw = (d.rawMaster && d.rawMaster[s.key]) || (d[`bab${s.babNum}`]) || {};
      const rowObj = { ...raw };
      rowObj.kecamatan = d.nama_proper || d.nama;
      rows.push(rowObj);
    });
    const ws = XLSX.utils.json_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, s.key);
  });

  const fileName = `cadangan_data_aktif_smartgraf_kcda_${new Date().toISOString().slice(0,10)}.xlsx`;
  XLSX.writeFile(wb, fileName);
  showToast("success", "Cadangan Data Aktif Terunduh! 💾", `Berkas '${fileName}' berhasil disimpan.`);
}
